def dot(a, b):
    if not a or not b or len(a) != len(b):
        raise ValueError("length mismatch")
    return sum(x * y for x, y in zip(a, b))

def matmul(a, b):
    rows_a, inner = len(a), len(a[0])
    if any(len(row) != inner for row in a):
        raise ValueError("inner dimensions must match")
    if not b or len(b[0]) == 0:
        return [[] for _ in range(rows_a)]
    cols_b = len(b[0])
    if len(b) != inner or any(len(row) != cols_b for row in b):
        raise ValueError("inner dimensions must match")
    return [[sum(a[i][k] * b[k][j] for k in range(inner)) for j in range(cols_b)] for i in range(rows_a)]

