import math

def pca_reduce(feature_matrix, n_components):
    n = len(feature_matrix)
    d = len(feature_matrix[0])
    mean = [sum(row[i] for row in feature_matrix) / n for i in range(d)]
    centered = [[row[i] - mean[i] for i in range(d)] for row in feature_matrix]

    cov = [
        [
            sum(centered[r][i] * centered[r][j] for r in range(n)) / (n - 1)
            for j in range(d)
        ]
        for i in range(d)
    ]

    def top_eigenvector(matrix):
        v = [1.0 / math.sqrt(d) for _ in range(d)]
        for _ in range(200):
            new = [sum(matrix[r][c] * v[c] for c in range(d)) for r in range(d)]
            norm = math.sqrt(sum(x * x for x in new))
            if norm == 0:
                return [0.0] * d, 0.0
            v = [x / norm for x in new]
        eigenvalue = sum(v[i] * matrix[i][j] * v[j] for i in range(d) for j in range(d))
        return v, max(eigenvalue, 0.0)

    components = []
    eigenvalues = []
    residual = [row[:] for row in cov]
    for _ in range(min(n_components, d)):
        vector, eigenvalue = top_eigenvector(residual)
        components.append(vector)
        eigenvalues.append(eigenvalue)
        residual = [
            [
                residual[i][j] - eigenvalue * vector[i] * vector[j]
                for j in range(d)
            ]
            for i in range(d)
        ]

    projected = [
        [sum(centered[r][i] * component[i] for i in range(d)) for component in components]
        for r in range(n)
    ]
    total = sum(eigenvalues)
    if total == 0:
        variance_ratio = [0.0 for _ in components]
    else:
        variance_ratio = [value / total for value in eigenvalues]
    return projected, variance_ratio

