def count_objects(mask):
    n = int(len(mask) ** 0.5)  # square image size
    visited = set()
    object_count = 0

    def is_object(idx):
        return 0 <= idx < len(mask) and mask[idx]['is_object']

    def neighbors(idx):
        r = idx // n
        c = idx % n
        results = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                results.append(nr * n + nc)
        return results

    for idx in range(len(mask)):
        if is_object(idx) and idx not in visited:
            object_count += 1
            # BFS to mark all connected object pixels
            queue = [idx]
            visited.add(idx)
            while queue:
                current = queue.pop(0)
                for nb in neighbors(current):
                    if is_object(nb) and nb not in visited:
                        visited.add(nb)
                        queue.append(nb)

    return object_count

